export type IconName = keyof typeof ICONS;

export function Icon({
  name,
  size = 16,
  color = "currentColor",
  opacity,
}: {
  name: IconName;
  size?: number;
  color?: string;
  opacity?: number;
}) {
  const def = ICONS[name];
  if (!def) {
    // eslint-disable-next-line no-console
    console.warn("[ocm] missing icon:", name);
    return null;
  }
  return (
    <Svg
      width={size}
      height={size}
      viewBox={def.viewBox}
      fill="none"
      opacity={opacity}
      accessibilityElementsHidden
    >
      {def.paths.map((p, i) => (
        <Path
          key={i}
          d={p.d}
          stroke={p.fill ? "none" : color}
          strokeWidth={1.6}
          strokeLinecap="square"
          strokeLinejoin="miter"
          fill={p.fill ? color : "none"}
        />
      ))}
    </Svg>
  );
}

