/** Brand colours. Drive lists one colour per subpath of its mark. */
const BRAND_COLORS: Record<string, string[]> = {
  dropbox: ["#0061FF"],
  gdrive: ["#FFBA00", "#0066DA", "#00AC47"],
  openai: ["#000000"],
  anthropic: ["#D97757"],
};

/** Splits a path with several subpaths so each can be filled separately. */
function subpaths(d: string): string[] {
  return d
    .split(/(?=M)/)
    .map((p) => p.trim())
    .filter(Boolean);
}


/**
 * Google Drive's 2026 mark: a rounded-triangle mask over three gradient wedges.
 * Ported from the official SVG, so it needs its own component rather than the
 * single-path BrandIcon table.
 */
export function DriveIcon({ size = 16 }: { size?: number }) {
  return (
    <Svg width={size} height={size} viewBox="0 0 800 741.3696" fill="none">
      <Defs>
        <LinearGradient id="dr-b" x1="193.6" x2="103.09" y1="165.6" y2="111.21" gradientUnits="userSpaceOnUse">
          <Stop offset="0.09" stopColor="#ffe921" />
          <Stop offset="1" stopColor="#fec700" />
        </LinearGradient>
        <LinearGradient id="dr-c" x1="114.4" x2="15.53" y1="181.61" y2="121.8" gradientUnits="userSpaceOnUse">
          <Stop offset="0.15" stopColor="#a9a8ff" />
          <Stop offset="0.33" stopColor="#6d97ff" />
          <Stop offset="0.48" stopColor="#3186ff" />
        </LinearGradient>
        <LinearGradient id="dr-d" x1="128.88" x2="28.7" y1="37.88" y2="84.64" gradientUnits="userSpaceOnUse">
          <Stop offset="0.55" stopColor="#0ebc5f" />
          <Stop offset="0.85" stopColor="#78c9ff" />
        </LinearGradient>
        <Mask id="dr-a" maskUnits="userSpaceOnUse" x="12" y="18" width="168" height="154">
          <Path
            fill="#fff"
            d="M63.09 37c14.626-25.333 51.193-25.334 65.819 0l45.033 78c14.626 25.334-3.657 57.001-32.91 57.001H50.967c-29.253 0-47.536-31.667-32.91-57.001Z"
          />
        </Mask>
      </Defs>
      <G mask="url(#dr-a)" transform="matrix(4.8140532,0,0,4.8140532,-62.146701,-86.652356)">
        <Path fill="url(#dr-b)" d="M206.905 172.02h-91.888l-19.015-32.934 45.944-79.578Z" />
        <Path fill="url(#dr-c)" d="M-14.919 172.006 50.04 59.494v.002L31.032 92.422h38.02L115 172.004l-129.918.001Z" />
        <Path fill="url(#dr-d)" d="M96.007-20.085 141.954 59.5l-19.011 32.928H31.048Z" />
      </G>
    </Svg>
  );
}

export function BrandIcon({
  providerID,
  size = 13,
  color = "currentColor",
  colored,
}: {
  providerID: string;
  size?: number;
  color?: string;
  colored?: boolean;
}) {
  const b = BRANDS[providerID];
  if (!b) {
    // No brand mark on file: a lettermark reads far better than a generic glyph.
    const letter = (providerID || "?").replace(/^custom_/, "").trim().charAt(0).toUpperCase() || "?";
    return (
      <View
        style={{
          width: size,
          height: size,
          borderRadius: Math.round(size * 0.26),
          borderWidth: 1.3,
          borderColor: color,
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        <Text style={{ fontSize: Math.round(size * 0.6), lineHeight: Math.round(size * 0.78), fontWeight: "700", color }}>
          {letter}
        </Text>
      </View>
    );
  }
  const palette = colored ? BRAND_COLORS[providerID] : undefined;
  if (palette) {
    const parts = subpaths(b.d);
    return (
      <Svg width={size} height={size} viewBox={b.viewBox} fill="none">
        {parts.map((d, idx) => (
          <Path key={idx} d={d} fill={palette[idx % palette.length]} />
        ))}
      </Svg>
    );
  }
  return (
    <Svg width={size} height={size} viewBox={b.viewBox} fill="none">
      <Path d={b.d} fill={color} />
    </Svg>
  );
}


